body.content:
[
  {
    "name": "theme_info",
    "theme_name": "Broadcast",
    "theme_version": "8.1.1",
    "theme_author": "Presidio Creative",
    "theme_support_url": "https://broadcast.presidiocreative.com/support/contacting-support",
    "theme_documentation_url": "https://broadcast.presidiocreative.com"
  },
  {
    "name": "Colors",
    "settings": [
      {
        "type": "color_scheme_group",
        "id": "color_schemes",
        "definition": [
          {
            "type": "header",
            "content": "Section"
          },
          {
            "type": "color",
            "id": "section_text",
            "label": "Text",
            "default": "#282C2E",
            "alpha": true
          },
          {
            "type": "color",
            "id": "section_bg",
            "label": "Background",
            "default": "#ffffff",
            "alpha": true
          },
          {
            "type": "color",
            "id": "section_bg_light",
            "label": "Light background",
            "default": "#F7F9FA",
            "info": "Used for background accents on the home page",
            "alpha": true
          },
          {
            "type": "color_background",
            "id": "section_bg_gradient",
            "label": "Background gradient",
            "info": "Background gradient replaces background where possible."
          },
          {
            "type": "header",
            "content": "Primary button"
          },
          {
            "type": "color",
            "id": "btn_primary_bg",
            "label": "Background",
            "default": "#AB8C52",
            "alpha": true
          },
          {
            "type": "color",
            "id": "btn_primary_text",
            "label": "Text",
            "default": "#fff",
            "alpha": true
          },
          {
            "type": "color",
            "id": "btn_primary_border",
            "label": "Outline and text",
            "default": "#AB8C52",
            "alpha": true
          },
          {
            "type": "header",
            "content": "Secondary button"
          },
          {
            "type": "color",
            "id": "btn_secondary_bg",
            "label": "Background",
            "default": "#8191A4",
            "alpha": true
          },
          {
            "type": "color",
            "id": "btn_secondary_text",
            "label": "Text",
            "default": "#212121",
            "alpha": true
          },
          {
            "type": "color",
            "id": "btn_secondary_border",
            "label": "Outline and text",
            "default": "#8191A4",
            "alpha": true
          },
          {
            "type": "header",
            "content": "Additional"
          },
          {
            "type": "color",
            "id": "accent",
            "label": "Accent",
            "default": "#E03386",
            "alpha": true
          },
          {
            "type": "color",
            "id": "lines_and_border",
            "label": "Lines and borders",
            "default": "#F3F3F3",
            "alpha": true
          },
          {
            "type": "color",
            "id": "overlay",
            "label": "Overlay",
            "default": "#0000004D",
            "alpha": true
          },
          {
            "type": "color",
            "id": "links",
            "label": "Links",
            "default": "#282C2E",
            "alpha": true
          }
        ],
        "role": {
          "background": {
            "solid": "section_bg",
            "gradient": "section_bg_gradient"
          },
          "text": "section_text",
          "primary_button": "btn_primary_bg",
          "on_primary_button": "btn_primary_text",
          "primary_button_border": "btn_primary_border",
          "secondary_button": "btn_secondary_bg",
          "on_secondary_button": "btn_secondary_text",
          "secondary_button_border": "btn_secondary_border",
          "icons": "section_text",
          "links": "links"
        }
      },
      {
        "type": "color_scheme",
        "id": "color_scheme",
        "default": "scheme_1",
        "label": "Default color scheme"
      },
      {
        "type": "header",
        "content": "Header"
      },
      {
        "type": "color",
        "id": "menu_bg_color",
        "label": "Background",
        "default": "#ffffff",
        "alpha": true
      },
      {
        "type": "color",
        "id": "header_link",
        "label": "Navigation",
        "default": "#282C2E",
        "alpha": true
      },
      {
        "type": "color",
        "id": "submenu_bg_color",
        "label": "Dropdown background",
        "default": "#ffffff",
        "alpha": true
      },
      {
        "type": "color",
        "id": "submenu_link_color",
        "label": "Dropdown navigation",
        "default": "#282C2E",
        "alpha": true
      },
      {
        "type": "color",
        "id": "menu_transparent_color",
        "label": "Transparent navigation",
        "default": "#ffffff",
        "alpha": true
      },
      {
        "type": "header",
        "content": "Product"
      },
      {
        "type": "color",
        "id": "sale_color",
        "label": "Sale",
        "default": "#d20000",
        "alpha": true
      }
    ]
  },
  {
    "name": "Typography",
    "settings": [
      {
        "type": "header",
        "content": "Header navigation"
      },
      {
        "type": "font_picker",
        "id": "type_nav_font",
        "label": "Font",
        "default": "poppins_n4"
      },
      {
        "type": "range",
        "id": "nav_font_size",
        "min": 10,
        "max": 50,
        "step": 1,
        "unit": "px",
        "label": "Font size",
        "default": 16
      },
      {
        "type": "range",
        "id": "nav_letter_spacing",
        "min": -25,
        "max": 200,
        "step": 25,
        "unit": "%",
        "label": "Letter spacing",
        "default": 0
      },
      {
        "type": "checkbox",
        "id": "type_nav_caps",
        "label": "Uppercase",
        "default": false
      },
      {
        "type": "header",
        "content": "Body text"
      },
      {
        "type": "font_picker",
        "id": "type_base_font",
        "label": "Font",
        "default": "poppins_n4"
      },
      {
        "type": "range",
        "id": "base_font_size",
        "min": 12,
        "max": 22,
        "step": 1,
        "unit": "px",
        "label": "Base size",
        "default": 16
      },
      {
        "type": "range",
        "id": "body_letter_spacing",
        "min": -25,
        "max": 200,
        "step": 25,
        "unit": "%",
        "label": "Letter spacing",
        "default": 0
      },
      {
        "type": "header",
        "content": "Subheadings"
      },
      {
        "type": "font_picker",
        "id": "type_subheading_font",
        "label": "Font",
        "default": "poppins_n4"
      },
      {
        "type": "range",
        "id": "sub_letter_spacing",
        "min": -25,
        "max": 200,
        "step": 25,
        "unit": "%",
        "label": "Letter spacing",
        "default": 100
      },
      {
        "type": "checkbox",
        "id": "type_sub_uppercase",
        "label": "Uppercase",
        "default": true
      },
      {
        "type": "range",
        "id": "subheading_size_desktop",
        "min": 10,
        "max": 60,
        "step": 1,
        "unit": "px",
        "label": "Desktop size",
        "default": 16
      },
      {
        "type": "range",
        "id": "subheading_size_mobile",
        "min": 10,
        "max": 60,
        "step": 1,
        "unit": "px",
        "label": "Mobile size",
        "default": 14
      },
      {
        "type": "header",
        "content": "Headings"
      },
      {
        "type": "font_picker",
        "id": "type_header_font",
        "label": "Font",
        "default": "poppins_n5"
      },
      {
        "type": "range",
        "id": "heading_letter_spacing",
        "min": -25,
        "max": 200,
        "step": 25,
        "unit": "%",
        "label": "Letter spacing",
        "default": 0
      },
      {
        "type": "checkbox",
        "id": "type_header_uppercase",
        "label": "Uppercase",
        "default": false
      },
      {
        "type": "paragraph",
        "content": "Desktop sizes"
      },
      {
        "type": "range",
        "id": "heading_mini",
        "min": 10,
        "max": 50,
        "step": 1,
        "unit": "px",
        "label": "Mini",
        "default": 10
      },
      {
        "type": "range",
        "id": "heading_x_small",
        "min": 10,
        "max": 50,
        "step": 1,
        "unit": "px",
        "label": "Extra small",
        "default": 16
      },
      {
        "type": "range",
        "id": "heading_small",
        "min": 10,
        "max": 75,
        "step": 1,
        "unit": "px",
        "label": "Small",
        "default": 20
      },
      {
        "type": "range",
        "id": "heading_medium",
        "min": 10,
        "max": 100,
        "step": 1,
        "unit": "px",
        "label": "Medium",
        "default": 30
      },
      {
        "type": "range",
        "id": "heading_large",
        "min": 10,
        "max": 150,
        "step": 2,
        "unit": "px",
        "label": "Large",
        "default": 40
      },
      {
        "type": "range",
        "id": "heading_x_large",
        "min": 10,
        "max": 200,
        "step": 2,
        "unit": "px",
        "label": "Extra large",
        "default": 50
      },
      {
        "type": "paragraph",
        "content": "Mobile sizes"
      },
      {
        "type": "range",
        "id": "heading_mini_mobile",
        "min": 10,
        "max": 50,
        "step": 1,
        "unit": "px",
        "label": "Mini",
        "default": 10
      },
      {
        "type": "range",
        "id": "heading_x_small_mobile",
        "min": 10,
        "max": 50,
        "step": 1,
        "unit": "px",
        "label": "Extra small",
        "default": 12
      },
      {
        "type": "range",
        "id": "heading_small_mobile",
        "min": 10,
        "max": 75,
        "step": 1,
        "unit": "px",
        "label": "Small",
        "default": 16
      },
      {
        "type": "range",
        "id": "heading_medium_mobile",
        "min": 10,
        "max": 100,
        "step": 1,
        "unit": "px",
        "label": "Medium",
        "default": 24
      },
      {
        "type": "range",
        "id": "heading_large_mobile",
        "min": 10,
        "max": 150,
        "step": 2,
        "unit": "px",
        "label": "Large",
        "default": 32
      },
      {
        "type": "range",
        "id": "heading_x_large_mobile",
        "min": 10,
        "max": 200,
        "step": 5,
        "unit": "px",
        "label": "Extra large",
        "default": 45
      }
    ]
  },
  {
    "name": "Buttons",
    "settings": [
      {
        "type": "font_picker",
        "id": "type_btn_font",
        "label": "Font",
        "default": "poppins_n4"
      },
      {
        "type": "select",
        "id": "btn_border_style",
        "label": "Style",
        "default": "square",
        "options": [
          { "label": "Square", "value": "square" },
          { "label": "Rounded", "value": "rounded" },
          { "label": "Pill", "value": "pill" }
        ]
      },
      {
        "type": "range",
        "id": "btn_size",
        "min": 10,
        "max": 24,
        "step": 1,
        "unit": "px",
        "label": "Font size",
        "default": 13
      },
      {
        "type": "range",
        "id": "btn_letter_spacing",
        "min": -25,
        "max": 200,
        "step": 25,
        "unit": "%",
        "label": "Letter spacing",
        "default": 100
      },
      {
        "type": "checkbox",
        "id": "btn_caps",
        "label": "Uppercase",
        "default": true
      },
      {
        "type": "header",
        "content": "Size"
      },
      {
        "type": "range",
        "id": "button_small",
        "min": 1,
        "max": 50,
        "step": 1,
        "unit": "px",
        "label": "Small",
        "default": 7
      },
      {
        "type": "range",
        "id": "button_medium",
        "min": 1,
        "max": 50,
        "step": 1,
        "unit": "px",
        "label": "Medium",
        "default": 12
      },
      {
        "type": "range",
        "id": "button_large",
        "min": 1,
        "max": 50,
        "step": 1,
        "unit": "px",
        "label": "Large",
        "default": 16
      }
    ]
  },
  {
    "name": "Layout",
    "settings": [
      {
        "type": "select",
        "id": "grid_style",
        "label": "Grid style",
        "options": [
          { "value": "classic", "label": "Classic" },
          { "value": "compact", "label": "Compact" }
        ],
        "default": "classic"
      },
      {
        "type": "header",
        "content": "Appearance"
      },
      {
        "type": "select",
        "id": "dots_style",
        "label": "Slider navigation style",
        "options": [
          { "value": "hidden", "label": "Hidden" },
          { "value": "circle", "label": "Circle" },
          { "value": "line", "label": "Line"}
        ],
        "default": "hidden"
      },
      {
        "type": "select",
        "id": "icon_style",
        "label": "Icon style",
        "default": "1",
        "options": [
          { "value": "1", "label": "Regular" },
          { "value": "1.5", "label": "Medium" },
          { "value": "2", "label": "Bold" }
        ]
      },
      {
        "type": "header",
        "content": "Products"
      },
      {
        "type": "select",
        "id": "show_image_gray_bg",
        "label": "Show gray background",
        "default": "none",
        "options": [
          { "value": "behind", "label": "Behind images" },
          { "value": "front", "label": "In front of images" },
          { "value": "none", "label": "None" }
        ]
      },
      {
        "type": "header",
        "content": "Animations"
      },
      {
        "type": "checkbox",
        "id": "animations_enable",
        "label": "Enable animations",
        "default": true
      },
      {
        "type": "checkbox",
        "id": "parallax_enable",
        "label": "Enable image parallax",
        "info": "Some large images will animate movement opposite to the scroll direction.",
        "default": false
      },
      {
        "type": "header",
        "content": "Design Elements"
      },
      {
        "type": "checkbox",
        "id": "product_grid_outline",
        "label": "Enable borders",
        "default": true,
        "info": "For Featured collection, Collection list and Blog posts."
      },
      {
        "type": "checkbox",
        "id": "enable_superscript",
        "label": "Enable superscript",
        "default": false,
        "info": "Show how many products are in a collection"
      },
      {
        "type": "header",
        "content": "Buttons"
      },
      {
        "type": "checkbox",
        "id": "show_scroll_top_button",
        "label": "Show \"Scroll to top\" button",
        "default": false
      },
      {
        "type": "header",
        "content": "Loading icon",
        "info": "Icon appears while site is loading"
      },
      {
        "type": "image_picker",
        "id": "loading_image_1",
        "label": "Image 1",
        "info": "300 x 90px .jpg recommended."
      },
      {
        "type": "image_picker",
        "id": "loading_image_2",
        "label": "Image 2",
        "info": "300 x 90px .jpg recommended."
      },
      {
        "type": "range",
        "id": "loading_image_width",
        "label": "Width",
        "unit": "px",
        "min": 100,
        "max": 180,
        "step": 10,
        "default": 100
      }
    ]
  },
  {
    "name": "Search",
    "settings": [
      {
        "type": "checkbox",
        "id": "predictive_search_enabled",
        "label": "Enable search suggestions",
        "default": true
      },
      {
        "type": "header",
        "content": "Empty search"
      },
      {
        "type": "link_list",
        "id": "empty_search_menu",
        "label": "Menu"
      },
      {
        "type": "product_list",
        "id": "empty_search_product_list",
        "label": "Products",
        "limit": 5
      }
    ]
  },
  {
    "name": "Social media",
    "settings": [
      {
        "type": "header",
        "content": "Social links"
      },
      {
        "type": "text",
        "id": "instagram_link",
        "label": "Instagram",
        "info": "https://instagram.com/shopify"
      },
      {
        "type": "text",
        "id": "facebook_link",
        "label": "Facebook",
        "info": "https://facebook.com/shopify"
      },
      {
        "type": "text",
        "id": "twitter_link",
        "label": "X (Twitter)",
        "info": "https://twitter.com/shopify"
      },
      {
        "type": "text",
        "id": "tiktok_link",
        "label": "TikTok",
        "info": "https://tiktok.com/@shopify"
      },
      {
        "type": "text",
        "id": "pinterest_link",
        "label": "Pinterest",
        "info": "https://pinterest.com/shopify"
      },
      {
        "type": "text",
        "id": "tumblr_link",
        "label": "Tumblr",
        "info": "http://shopify.tumblr.com"
      },
      {
        "type": "text",
        "id": "youtube_link",
        "label": "YouTube",
        "info": "https://youtube.com/shopify"
      },
      {
        "type": "text",
        "id": "vimeo_link",
        "label": "Vimeo",
        "info": "https://vimeo.com/shopify"
      },
      {
        "type": "text",
        "id": "linkedin_link",
        "label": "LinkedIn",
        "info": "https://linkedin.com/company/shopify"
      },
      {
        "type": "text",
        "id": "snapchat_link",
        "label": "Snapchat",
        "info": "https://snapchat.com/add/shopify"
      },
      {
        "type": "text",
        "id": "feed_link",
        "label": "Blog feed",
        "info": "http://store.myshopify.com/blogs/news.atom"
      },
      {
        "type": "header",
        "content": "Sharing options"
      },
      {
        "type": "checkbox",
        "id": "share_facebook",
        "label": "Share on Facebook",
        "default": true
      },
      {
        "type": "checkbox",
        "id": "share_twitter",
        "label": "Tweet on Twitter",
        "default": true
      },
      {
        "type": "checkbox",
        "id": "share_pinterest",
        "label": "Pin on Pinterest",
        "default": true
      }
    ]
  },
  {
    "name": "Pagination",
    "settings": [
      {
        "type": "checkbox",
        "id": "enable_infinity_scroll",
        "label": "Enable infinity scroll",
        "default": false,
        "info": "It applies to the Collection page"
      }
    ]
  },
  {
    "name": "Product grid",
    "settings": [
      {
        "type": "paragraph",
        "content": "For collections, search results, and sections with products in a grid."
      },
      {
        "type": "select",
        "id": "product_grid_font_size",
        "label": "Text size",
        "info": "Automatically generated by the base size.",
        "default": "body-medium",
        "options": [
          {"value": "body-x-small", "label": "Extra small"},
          {"value": "body-small", "label": "Small"},
          {"value": "body-medium", "label": "Medium"},
          {"value": "body-large", "label": "Large"},
          {"value": "body-x-large", "label": "Extra large"}
        ]
      },
      {
        "type": "checkbox",
        "id": "product_grid_center",
        "label": "Center text",
        "default": true
      },
      {
        "type": "checkbox",
        "id": "overlay_text",
        "label": "Overlay text",
        "info": "Only works with tall images",
        "default": false
      },
      {
        "type": "checkbox",
        "id": "show_recently_viewed_indicator",
        "label": "Show recently viewed indicator",
        "default": false
      },
      {
        "type": "header",
        "content": "Images"
      },
      {
        "type": "checkbox",
        "label": "Show additional images",
        "id": "image_hover_enable",
        "default": true
      },
      {
        "type": "range",
        "id": "image_hover_limit",
        "min": 2,
        "max": 5,
        "step": 1,
        "label": "Limit product images",
        "default": 2
      },
      {
        "type": "range",
        "id": "product_grid_aspect_ratio",
        "min": 0.5,
        "max": 1.5,
        "step": 0.1,
        "unit": ":1",
        "label": "Product image aspect ratio",
        "info": "Wide to tall",
        "default": 1
      },
      {
        "type": "header",
        "content": "Quick add"
      },
      {
        "type": "checkbox",
        "id": "quickview_enable",
        "label": "Enable quick add. [Learn more](https://broadcast.presidiocreative.com/collections/collection-pages/quick-add)",
        "default": true
      },
      {
        "type": "checkbox",
        "id": "show_gift_card_recipient",
        "label": "Show recipient information form for gift card products",
        "default": false,
        "info": "Gift card products can optionally be sent direct to a recipient along with a personal message."
      },
      {
        "type": "color",
        "id": "quick_add_bg_color",
        "label": "Button background",
        "default": "#ffffff",
        "alpha": true
      },
      {
        "type": "color",
        "id": "quick_add_text_color",
        "label": "Button text",
        "default": "#000000",
        "alpha": true
      },
      {
        "type": "select",
        "id": "quick_add_mobile_style",
        "label": "Mobile style",
        "default": "button",
        "options": [
          { "value": "mini_button", "label": "Mini button" },
          { "value": "button", "label": "Button" }
        ]
      },
      {
        "type": "checkbox",
        "id": "quickview_hide_mobile",
        "label": "Hide on mobile",
        "default": false
      },
      {
        "type": "header",
        "content": "Swatches"
      },
      {
        "type": "checkbox",
        "label": "Show siblings on collections",
        "id": "show_siblings",
        "info": "Learn more about linked [color siblings](https://broadcast.presidiocreative.com/siblings/product-siblings/about-product-siblings)",
        "default": true
      },
      {
        "type": "checkbox",
        "label": "Show color swatches on collections",
        "id": "show_grid_swatches",
        "default": true
      },
      {
        "type": "header",
        "content": "Cutline"
      },
      {
        "type": "checkbox",
        "label": "Show cutline",
